entries[14310] = { ["name"] = "Eiskältefalle", ["text"] = "75 Mana\nSofort 15 sek. Abklingzeit\nEine Eiskältefalle platzieren, die den ersten sich nähernden Feind einfriert und 15 Sek. lang jegliche Aktion des Feindes verhindert. Jeglicher erlittener Schaden wird das Eis wieder brechen. Die Falle bleibt 1 Min. lang bestehen. Fallen können nur außerhalb von Kampfaktivitäten platziert werden. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14311] = { ["name"] = "Eiskältefalle", ["text"] = "100 Mana\nSofort 15 sek. Abklingzeit\nEine Eiskältefalle platzieren, die den ersten sich nähernden Feind einfriert und 20 Sek. lang jegliche Aktion des Feindes verhindert. Jeglicher erlittener Schaden wird das Eis wieder brechen. Die Falle bleibt 1 Min. lang bestehen. Fallen können nur außerhalb von Kampfaktivitäten platziert werden. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14313] = { ["name"] = "Wütenden Greif beschwören" }
entries[14314] = { ["name"] = "Sprengfalle" }
entries[14315] = { ["name"] = "Sprengfalle" }
entries[14316] = { ["name"] = "Sprengfalle", ["text"] = "395 Mana\nSofort 15 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht 145 bis 193 Feuerschaden und verbrennt 20 Sek. lang alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen 240 zusätzlichen Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Fallen können nur außerhalb von Kampfaktivitäten platziert werden. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14317] = { ["name"] = "Sprengfalle", ["text"] = "520 Mana\nSofort 15 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht 208 bis 265 Feuerschaden und verbrennt 20 Sek. lang alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen 330 zusätzlichen Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Fallen können nur außerhalb von Kampfaktivitäten platziert werden. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14318] = { ["name"] = "Aspekt des Falken", ["text"] = "35 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 35 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14319] = { ["name"] = "Aspekt des Falken", ["text"] = "50 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 50 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14320] = { ["name"] = "Aspekt des Falken", ["text"] = "70 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 70 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14321] = { ["name"] = "Aspekt des Falken", ["text"] = "90 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 90 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14322] = { ["name"] = "Aspekt des Falken", ["text"] = "110 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 110 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14323] = { ["name"] = "Mal des Jägers", ["text"] = "30 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 45. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[14324] = { ["name"] = "Mal des Jägers", ["text"] = "45 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 75. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[14325] = { ["name"] = "Mal des Jägers", ["text"] = "60 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 110. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[14326] = { ["name"] = "Wildtier ängstigen", ["text"] = "50 Mana 10 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 15 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
entries[14327] = { ["name"] = "Wildtier ängstigen", ["text"] = "75 Mana 10 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 20 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
