entries[14517] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 27 Punkt(e) Schaden bei einem Feind und erhöht seinen erlittenen Heiligschaden um 10 Punkt(e) pro Kreuzfahrerstoß. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[14518] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 50 Punkt(e) Schaden bei einem Feind und erhöht seinen erlittenen Heiligschaden um 20 Punkt(e) pro Kreuzfahrerstoß. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[14520] = { ["name"] = "Mentale Beweglichkeit", ["text"] = "Verringert die Manakosten Eurer Spontanzauber um 2%." }
entries[14521] = { ["name"] = "Meditation", ["text"] = "Ermöglicht, dass 5% Eurer Manaregeneration während des Zauberwirkens weiterläuft." }
entries[14522] = { ["name"] = "Unbezwingbarer Wille", ["text"] = "Erhöht Eure Chance, Betäubungs-, Furcht- und Stilleeffekten zu widerstehen, um weitere 3%." }
entries[14523] = { ["name"] = "Schweigsame Entschlossenheit", ["text"] = "Verringert die von Euren Zaubern verursachte Bedrohung um 4%." }
entries[14524] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 5%." }
entries[14525] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 10%." }
entries[14526] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 15%." }
entries[14527] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 20%." }
entries[14528] = { ["name"] = "Zauberstab-Spezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 25%." }
entries[14530] = { ["name"] = "Tempo", ["text"] = "Sofort\nErhöht das Lauftempo 10 Sek. lang um 40%." }
entries[14531] = { ["name"] = "Märtyrertum", ["text"] = "Gewährt Euch eine Chance von 50%, den Effekt 'Fokussiertes Zauberwirken' zu erhalten, der 6 Sek. lang anhält, nachdem Ihr Opfer eines kritischen Nahkampf- oder Distanzangriffs wart. Der Effekt 'Fokussiertes Zauberwirken' verhindert, dass Ihr Zauberzeit durch Euch zugefügten Schaden verliert. Zusätzlich wird Euer Widerstand gegenüber Unterbrechungseffekten um 10% erhöht.\n(Procchance: 50%)" }
entries[14532] = { ["name"] = "Krabblergift", ["text"] = "Wirken in 2 sek.\nErhöht den erlittenen körperlichen Schaden von in der Nähe befindlichen Feinden 5 Min. lang um 30%." }
entries[14533] = { ["name"] = "Abtrennung", ["text"] = "Sofort\nErhöht 5 Min. lang den von in der Nähe befindlichen Feinden erlittenen Feuer-, Frost- und Arkanschaden um 50%." }
entries[14534] = { ["name"] = "Stachelstich", ["text"] = "Sofort\nErhöht die Zeit zwischen Angriffen in der Nähe befindlicher Feinde 5 Min. lang um 54%." }
entries[14535] = { ["name"] = "Baggererkrankung", ["text"] = "Sofort\nVerringert alle Attribute von in der Nähe befindlichen Feinden 5 Min. lang um 25%." }
entries[14537] = { ["name"] = "Sechsdämonentasche", ["text"] = "30 Meter Reichweite\nSofort\nÜberzieht den Feind mit der Macht des Windes, des Feuers und all solchen Dingen!" }
entries[14538] = { ["name"] = "Auraschock", ["text"] = "Sofort\nVerringert das Zaubertempo von in der Nähe befindlichen Feinden 5 Min. lang um 35%." }
entries[14539] = { ["name"] = "Eitriges Enzym", ["text"] = "Sofort\nErhöht den erlittenen Naturschaden von in der Nähe befindlichen Feinden um 50% und erhöht den von ihnen erlittenen Schattenschaden um 50%. Hält 5 Min. lang an." }
